  function boardCard(d){const h=M.health(state,d)[0];return '<article class="deal-card"><h3>'+link('open-deal',d.title,d.id)+'</h3><p>'+esc(d.organisation)+'</p><strong class="amount number">'+money(d.value)+'</strong>'+(h?'<p>'+pill(h.label,h.tone)+'</p>':'<p>'+pill(d.outcome==='Open'?'Next action planned':d.outcome,d.outcome==='Won'?'success':'')+'</p>')+'<div class="card-bottom"><span class="inline">'+avatar(d.owner)+'<span class="small muted">'+fmt(d.close)+'</span></span>'+btn('board-snapshot','<span class="sr-only">Snapshot: '+esc(d.title)+'</span>','eye','data-id="'+d.id+'"','text-button')+'</div></article>';}
  function renderBoard(){if(ui.read==='denied'||ui.read==='failed'||ui.read==='loading'){renderDeal();return;}const rows=filteredDeals(),known=rows.filter(d=>d.value!==null),weight=rows.reduce((n,d)=>n+(M.weighted(state,d)||0),0);$('#workspace').innerHTML='<header class="board-header"><div class="inline between"><div><span class="eyebrow">Shared navigation preview</span><h1 id="page-title" tabindex="-1">Deals</h1></div><div class="actions">'+btn('pipeline','<span>'+esc(state.pipeline.name)+'</span>','sales','','pipeline-picker')+btn('guide','Review guide','info')+'</div></div></header><div class="board-toolbar"><div class="segmented" aria-label="Deals view">'+btn('board-view','Board','grid','data-id="board" aria-pressed="'+(ui.view==='board')+'"')+btn('board-view','List','list','data-id="list" aria-pressed="'+(ui.view==='list')+'"')+'</div><label class="search">Search opportunities<input type="search" data-filter="q" value="'+esc(ui.q)+'" placeholder="Deal, customer or reference"></label>'+btn('clear-filters','Clear filters','filter')+'</div><div class="board-filters"><label class="sr-only" for="board-owner">Deal owner</label><select id="board-owner" data-filter="owner"><option value="">All owners</option>'+F.users.filter(u=>u.role==='Sales owner').map(u=>'<option value="'+u.id+'" '+(ui.owner===u.id?'selected':'')+'>'+u.name+'</option>').join('')+'</select><label class="sr-only" for="board-outcome">Sales outcome</label><select id="board-outcome" data-filter="outcome">'+[['Open','Open deals'],['Won','Won deals'],['Lost','Lost deals'],['','All outcomes']].map(x=>'<option value="'+x[0]+'" '+(ui.outcome===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')+'</select><label class="sr-only" for="board-stage">Stage</label><select id="board-stage" data-filter="stage"><option value="">All stages</option>'+state.pipeline.stages.map(s=>'<option value="'+s.id+'" '+(ui.stage===s.id?'selected':'')+'>'+esc(s.name)+'</option>').join('')+'</select></div><div class="board-summary"><span><strong>'+rows.length+'</strong> matching deals</span><span><strong>'+money(known.reduce((n,d)=>n+d.value,0))+'</strong> known value</span><span><strong>'+rows.filter(d=>d.value===null).length+'</strong> not estimated</span><span><strong>'+ (state.pipeline.probability?money(weight):'Off')+'</strong> weighted</span></div><div id="content" tabindex="-1">'+(!rows.length?empty('No deals match this view','Clear or adjust the filters to find an opportunity.',btn('clear-filters','Clear filters','filter')):ui.view==='board'?'<div class="board-scroll"><div class="board">'+state.pipeline.stages.map(s=>'<section class="board-column"><header class="column-title">'+esc(s.name)+'<span>'+rows.filter(d=>d.stage===s.id).length+' deals</span></header>'+rows.filter(d=>d.stage===s.id).map(boardCard).join('')+'</section>').join('')+'</div></div>':'<div class="table-wrap"><table><caption>The same permitted synthetic deals as Board view.</caption><thead><tr><th>Opportunity</th><th>Stage / outcome</th><th>Owner</th><th>Expected close</th><th class="num">Value · AUD excl. GST</th></tr></thead><tbody>'+rows.map(d=>'<tr><td>'+link('open-deal',d.title,d.id)+'<p class="small muted">'+esc(d.organisation)+'</p></td><td data-label="Stage / outcome">'+esc(stageName(d))+' · '+d.outcome+'</td><td data-label="Owner">'+person(d.owner).name+'</td><td data-label="Expected close">'+fmt(d.close,true)+'</td><td data-label="Value" class="num">'+money(d.value)+'</td></tr>').join('')+'</tbody></table></div>')+'</div>';}
  function applyCapabilities(){const d=deal();if(!d)return;const ownerActions=['edit','scope-edit','stage','transfer','activity-add','activity-edit','task-add','task-edit','waiting','contact-edit','message-note','message-draft','document-add','delivery','outcome','pipeline','adopt-value'];document.querySelectorAll('[data-action]').forEach(b=>{if(ownerActions.includes(b.dataset.action)&&!can(d))b.disabled=true;});}
