  function openPanel(title,body,footer='',options={}){const p=$('#panel'),previous=p.open?panelContext?.returnElement:document.activeElement;panelContext={returnElement:previous,dirty:false,version:deal()?.version,...options};p.removeAttribute('aria-busy');p.className='dock '+(options.wide?'wide ':'')+(options.decision?'decision':'');$('#panel-title').textContent=title;$('#panel-kicker').textContent=options.kicker||'Deal Workspace';$('#panel-subtitle').textContent=options.subtitle||deal()?.ref||'CR-01 · r01';$('#panel-body').innerHTML=body;$('#panel-footer').innerHTML=footer;if(!p.open)p.showModal();p.scrollTop=0;$('#panel-body').scrollTop=0;applyCapabilities();requestAnimationFrame(()=>($('#panel-body').querySelector('[autofocus],input:not([type=hidden]),select,textarea')||$('#panel-title')).focus());}
